const TYPE_NAMES={page:'页面',header:'顶部栏',footer:'底部栏',navbar:'导航栏',sidebar:'侧边栏',toolbar:'工具栏',container:'容器',card:'卡片',section:'区块',list:'列表',listItem:'列表项',table:'表格',row:'列表行',column:'列',grid:'网格',button:'按钮',iconButton:'图标按钮',input:'输入框',textarea:'多行输入框',select:'下拉选择',checkbox:'复选框',radio:'单选项',switch:'开关',tab:'标签页',text:'文字',title:'标题',subtitle:'副标题',icon:'图标',image:'图片',avatar:'头像',divider:'分隔线',progress:'进度条',badge:'徽标',tag:'标签',dialog:'对话框',drawer:'侧边抽屉',bottomSheet:'底部弹层',mask:'遮盖层',unknown:'未知'};
